use super::*;use crate::original_audio::spatial::{Chance,Boundary};
fn field(mp:bool)->Game{let mut g=Game::new(0,1,480);g.map.original=true;g.multiplayer=mp;g.map.width=64;g.map.height=64;g.map.tiles=vec![0;4096];g.map.terrain_codes=vec![0;4096];g.map.native_terrain_plane=vec![0;16384];g.map.original_tiles=vec![0;4096];g.map.native_tile_plane=vec![0;16384];g.map.bridge_base=vec![-1;4096];g.map.bridge_hp=vec![1.];g.map.bridge_max_hp=vec![200.];g.units.clear();g.buildings.clear();g.objects.clear();g.crates.clear();g.walls.clear();g.sectors.clear();g.ai_teams.clear();g.native_world=None;g.native_strategy=None;g.import_native_world(&json!({"bridges":[{"id":0,"nativeSlot":0,"nativeOrientation":0,"x":640,"y":640,"w":192,"h":96,"hp":1,"maxHp":200}]}));g.native_view=Some(([0,0],[1024,1024]));g.native_feedback.ui_clock=500;g.native_feedback.sound_enabled=1;g.initialize_native_listener_mission();views(&mut g,[0,0],[400,400]);g}
fn views(g:&mut Game,h:[i16;2],v:[i16;2]){g.set_native_listener_settings(&json!({"0":{"soundEnabled":true,"view":{"camera":h,"size":[320,320]},"hardwareContext":"1:0"},"1":{"soundEnabled":true,"view":{"camera":v,"size":[320,320]},"hardwareContext":"1:0"}}));}
fn particle(g:&mut Game,slot:usize,point:[i16;2],sprite:i16){let s=g.native_world.as_mut().unwrap();let mut raw=[0;44];raw[6..8].copy_from_slice(&point[0].wrapping_sub(s.last_projection[0]).to_le_bytes());raw[8..10].copy_from_slice(&point[1].wrapping_sub(s.last_projection[1]).to_le_bytes());raw[26..28].copy_from_slice(&sprite.to_le_bytes());s.put_effect(slot,effects::Particle::from_bytes(raw));}
fn world(g:&Game)->Value{let s=g.native_world.as_ref().unwrap();json!({"tiles":g.map.tiles,"terrain":g.map.terrain_codes,"nativePlane":g.map.native_terrain_plane,"tilePlane":g.map.native_tile_plane,"originalTiles":g.map.original_tiles,"bridgeHp":g.map.bridge_hp,"effects":s.effects.iter().map(|p|p.as_ref().map(|p|p.bytes().to_vec())).collect::<Vec<_>>(),"rng":g.original_rng.words,"crt":g.native_cosmetic_rng,"blasts":g.blasts.iter().map(|b|(b.id,b.x,b.y,b.strength)).collect::<Vec<_>>(),"quiet":s.quiet_blasts,"mask":s.effect_world_mask4f,"worldSuppression":s.effect_world_suppression,"origin":s.effect_origin,"flags":s.effect_flags,"tint":s.effect_tint,"owner":s.effect_owner})}
fn samples(g:&Game)->Vec<(i64,i64)>{g.events.iter().filter(|e|e["kind"]=="nativeSample").map(|e|(e["sampleId"].as_i64().unwrap(),e["recipientTeam"].as_i64().unwrap_or(0))).collect()}
fn owner4(g:&mut Game){g.set_world_code(20*128+20,23);g.native_world.as_mut().unwrap().last_projection=[160,100];particle(g,0,[308,288],1138);g.finish_native_building_part_expiry(0,effects::View{camera:[0,0],clip:[0,0,1024,1024],world:[1024,1024],sine:0,cosine:0});}
#[test]fn spatial_audio_actual_owner4_bridge_reentry_stays_once_across_listener_views(){
 let(mut a,mut b)=(field(true),field(true));views(&mut b,[400,400],[0,0]);owner4(&mut a);owner4(&mut b);assert_eq!(world(&a),world(&b));assert_eq!(a.map.bridge_hp[0],0.);assert_eq!(samples(&a),[(1,0)]);assert_eq!(samples(&b),[(1,1)]);assert_eq!((a.native_audio.opportunity_gate,a.native_listener_audio.guest_audio.opportunity_gate),(1,0));assert_eq!((a.native_audio.explosion_cycle,a.native_listener_audio.guest_audio.explosion_cycle),(1,0));assert!(!a.events.iter().any(|e|e["kind"]=="nativeEffectSound"));assert!(a.events.iter().filter(|e|e["kind"]=="nativeSample").all(|e|e["nativeHardwareAudioContext"]=="1:0"));
 //The crate callback is a seeded real Raw44 stage. Double-camera audio sees
 //Guest50/50 while the following ordinary blast850/850 is outside its view.
 for g in[&mut a,&mut b]{particle(g,499,[850,850],473);let actions=effects::source_expiry_prefix(6,[850,850],473);g.execute_native_effect_actions(499,actions,effects::View{camera:[0,0],clip:[0,0,1024,1024],world:[1024,1024],sine:0,cosine:0});}
 assert_eq!(world(&a),world(&b));assert!(samples(&a).contains(&(30,1)));assert!(samples(&b).contains(&(30,0)));assert_eq!((a.native_audio.opportunity_gate,a.native_listener_audio.guest_audio.opportunity_gate),(1,1));
}
#[test]fn spatial_audio_sp_cameras_do_not_duplicate_native_rng_contacts_or_child_pools(){let(mut a,mut b)=(field(false),field(false));b.native_view=Some(([700,700],[320,320]));let before=a.original_rng.words;owner4(&mut a);owner4(&mut b);assert_eq!(world(&a),world(&b));assert_ne!(a.original_rng.words,before,"actual source constructors consume SP RNG once");assert_eq!(samples(&a),[(1,0)]);assert!(samples(&b).is_empty());assert_eq!(a.native_world.as_ref().unwrap().effects.iter().flatten().filter(|p|p.active&&p.sprite==250).count(),4);}
#[test]fn spatial_audio_first_suppressed_blast_prefix_is_before_environment_and_not_world_suppression(){let mut g=field(true);particle(&mut g,0,[100,100],250);g.native_world.as_mut().unwrap().effect_world_suppression=1;g.execute_native_effect_actions(0,vec![effects::Action::Blast{point:[100,100],strength:0,suppress_visual:true}],effects::View{camera:[0,0],clip:[0,0,1024,1024],world:[1024,1024],sine:0,cosine:0});assert_eq!(samples(&g),[(1,0)]);assert_eq!(g.native_audio.opportunity_gate,1);assert_eq!(g.native_audio.explosion_cycle,1);assert_eq!(g.native_world.as_ref().unwrap().effect_world_suppression,1);assert!(g.blasts.is_empty(),"existing environment-only world leaf remains distinct from a full420200 tail");}
#[test]fn spatial_audio_source_stage_rereads_current_raw_record_and_projection_without_active_filter(){let mut g=field(true);particle(&mut g,0,[450,450],250);g.set_world_code(SelfCell::at([450,450]),9);g.native_world.as_mut().unwrap().effects[0].as_mut().unwrap().active=false;g.execute_native_effect_actions(0,vec![effects::Action::ProbeFalling{point:[10,10]}],effects::View{camera:[0,0],clip:[0,0,1024,1024],world:[1024,1024],sine:0,cosine:0});assert_eq!(samples(&g),[(8,1)]);assert_eq!((g.blasts[0].x,g.blasts[0].y),(900.,900.));assert!(g.native_audio.opportunity_boundary.is_none());}
struct SelfCell;impl SelfCell{fn at(p:[i16;2])->i16{Game::world_cell(p)}}
#[test]fn spatial_audio_missing_stage_owner_is_a_boundary_not_the_old_vec_point(){let mut g=field(true);let before=world(&g);g.execute_native_effect_actions(3,vec![effects::Action::ProbeFalling{point:[10,10]}],effects::View{camera:[0,0],clip:[0,0,1024,1024],world:[1024,1024],sine:0,cosine:0});assert_eq!(world(&g),before);assert!(samples(&g).is_empty());assert_eq!(g.native_audio.opportunity_boundary,Some(Boundary::MissingEffectRecord(3)));assert_eq!(g.native_listener_audio.guest_audio.opportunity_boundary,Some(Boundary::MissingEffectRecord(3)));}
#[test]fn spatial_audio_gate_reset_is_main_only_and_cycle_stays_warm(){let mut g=field(true);g.native_audio.opportunity_gate=255;g.native_audio.explosion_cycle=7;g.native_listener_audio.guest_audio.opportunity_gate=1;g.native_listener_audio.guest_audio.explosion_cycle=3;let rng=g.original_rng.words;for _ in 0..12{g.step_native_ui_only(1./17.);}views(&mut g,[0,0],[400,400]);assert_eq!((g.native_audio.opportunity_gate,g.native_listener_audio.guest_audio.opportunity_gate),(255,1));g.initialize_native_listener_mission();assert_eq!((g.native_audio.opportunity_gate,g.native_listener_audio.guest_audio.opportunity_gate),(255,1));g.begin_native_spatial_audio_main();assert_eq!((g.native_audio.opportunity_gate,g.native_listener_audio.guest_audio.opportunity_gate),(0,0));assert_eq!((g.native_audio.explosion_cycle,g.native_listener_audio.guest_audio.explosion_cycle),(7,3));assert_eq!(g.original_rng.words,rng);}
#[test]fn spatial_audio_missing_listener_does_not_borrow_the_world_camera(){let mut g=field(true);g.set_native_listener_settings(&json!({"1":{"soundEnabled":true}}));g.emit_native_spatial_audio(Chance::Blast420200{point:[100,100],bounds:[1024,1024],mask4f:0,quiet:false});assert_eq!(samples(&g),[(1,0)]);assert_eq!(g.native_listener_audio.guest_audio.opportunity_gate,0);assert_eq!(g.native_listener_audio.guest_audio.explosion_cycle,0);assert_eq!(g.native_listener_audio.guest_audio.opportunity_boundary,Some(Boundary::MissingListenerView(1)));}
